/**
 * #95 — a brand-new repo's `not-in-fleet` is advisory, never a failing finding,
 * for `NEW_REPO_GRACE_HOURS` (24h) after its first commit; past that it fails
 * exactly as before.
 *
 * `WolffM/hadoku-housemodel` was created 2026-10-04T21:04Z. The roster is
 * regenerated by hadoku_site's `reconcile-fleet-coverage.yml` (scheduled
 * `30 12` / `0 14` UTC, observed to fire hours late), so `ci:header-fleet`
 * paged `@here` at 06:11Z with `not-in-fleet` before the regeneration could
 * possibly have run. The grace covers exactly that window.
 *
 * Age is measured from the FIRST commit reachable from the repo's shipped
 * default branch, read from the fleet-source mirror (full history, never
 * shallow) — a read-only proxy for repo creation, no GitHub REST call. A repo
 * whose newest commit is 1h old but whose first is 100h old is OLD, and is
 * exercised below.
 *
 * Exercised as a CLI: a throwaway manifest dir and site root, the repos as
 * fixture REMOTES read through fleet-source (lib/fleet-source-fixture.mjs), a
 * `gh` shim listing those remotes as the owner's account, and `REPOS_DIR`
 * pointed at an EMPTY directory — nothing there may matter (fleet-manager#7).
 * Everything is pointed at explicitly, so an ambient `HADOKU_SITE_ROOT=/nonexistent
 * REPOS_DIR=/nonexistent` — the blinding CI runs this file with — is
 * overridden, never inherited, and `--json` is read back as structured data.
 *
 * `FLEET` (the `uiApp` facet) and `KNOWN_CONSUMERS` (`wolffmConsumer`) are both
 * empty in every fixture here, so the only things that can ever produce a
 * finding are the two cross-cutting rules at the bottom of the script: "is the
 * FLEET list complete" (`not-in-fleet` / `new-repo-grace`) and the templates
 * sweep. The six template directories are created (empty, non-git-ignored) so
 * the templates sweep finds real directories and reports nothing, isolating
 * the thing under test.
 *
 * Every git fixture uses `cleanGitEnv` (never `git config user.*` — see
 * `scripts/lib/test-git-identity.mjs` and `hook-safe-tests.test.mjs`), and
 * dates are supplied through `GIT_AUTHOR_DATE`/`GIT_COMMITTER_DATE`, never by
 * touching the system clock.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { chmodSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { fixtureRemotes, poisonedClone } from './lib/fleet-source-fixture.mjs';
import { cleanGitEnv } from './lib/test-git-identity.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const SCRIPT = join(HERE, 'check-header-fleet.mjs');

/** The ambient environment with every GIT_* variable removed — see
 *  lib/hook-safe-tests.test.mjs and lib/test-git-identity.mjs. */
const NO_GIT_ENV = Object.fromEntries(
	Object.entries(process.env).filter(([k]) => !k.startsWith('GIT_'))
);

const TEMPLATES = [
	'templates/ui-app',
	'templates/tunnel-contained',
	'templates/tunnel',
	'templates/tunnel-proxy',
	'templates/tunnel-python',
	'templates/worker',
];

/** `git -C dir <args>`, with a clean env and an explicit `cwd` — belt and
 *  braces against `GIT_DIR` overriding `-C` from an inherited hook env. */
function gitIn(dir, args, extraEnv) {
	execFileSync('git', ['-C', dir, ...args], {
		stdio: ['ignore', 'pipe', 'pipe'],
		env: cleanGitEnv(extraEnv),
		cwd: dir,
	});
}

/**
 * `gh repo list` answered with every fixture remote, so the owner's account is
 * exactly what the test pushed. Any other `gh` call is a test bug.
 */
const GH_SHIM = `#!/bin/sh
case "$1 $2" in
"repo list")
	printf '['
	sep=''
	for d in "$FIXTURE_REMOTES"/WolffM/*.git; do
		[ -d "$d" ] || continue
		printf '%s{"nameWithOwner":"WolffM/%s","isEmpty":false}' "$sep" "$(basename "$d" .git)"
		sep=','
	done
	printf ']\\n'
	;;
*) echo "unexpected gh $*" >&2; exit 1 ;;
esac
`;

/** A throwaway manifest dir, site root (with the six real template dirs, so
 *  the templates sweep finds something real and reports nothing), an EMPTY
 *  repos dir, and fixture remotes, with an empty `uiApp`/`wolffmConsumer`
 *  roster. */
function fixture({ repos = [], facets = {} } = {}) {
	const remotes = fixtureRemotes('header-fleet-grace-');
	const root = remotes.root;
	const manifestDir = join(root, 'manifest');
	const siteRoot = join(root, 'site');
	const reposDir = join(root, 'repos');
	const bin = join(root, 'bin');
	mkdirSync(manifestDir, { recursive: true });
	mkdirSync(reposDir, { recursive: true });
	mkdirSync(bin, { recursive: true });
	writeFileSync(join(bin, 'gh'), GH_SHIM);
	chmodSync(join(bin, 'gh'), 0o755);
	for (const t of TEMPLATES) mkdirSync(join(siteRoot, t), { recursive: true });
	gitIn(siteRoot, ['init', '-q']);

	writeFileSync(join(manifestDir, 'fleet-runner-coverage.json'), JSON.stringify({ repos, facets }));

	return { root, remotes, manifestDir, siteRoot, reposDir, bin };
}

function cleanup(fx) {
	rmSync(fx.root, { recursive: true, force: true });
}

/**
 * Push `commits` — each `{ files, ageHours? }` — to the fixture remote for
 * `WolffM/<name>`, in order, each dated `ageHours` ago. Dated through
 * `GIT_AUTHOR_DATE`/`GIT_COMMITTER_DATE`, which `remotes.push` does not take.
 */
function pushDated(fx, name, commits) {
	const bare = fx.remotes.remote(`WolffM/${name}`);
	const work = join(fx.root, 'dated', name);
	mkdirSync(bare, { recursive: true });
	gitIn(bare, ['init', '-q', '--bare', '-b', 'main']);
	gitIn(bare, ['config', 'uploadpack.allowFilter', 'true']);
	gitIn(bare, ['config', 'uploadpack.allowAnySHA1InWant', 'true']);
	mkdirSync(work, { recursive: true });
	gitIn(work, ['init', '-q', '-b', 'main']);
	for (const { files, ageHours = 1000 } of commits) {
		for (const [rel, body] of Object.entries(files)) {
			mkdirSync(dirname(join(work, rel)), { recursive: true });
			writeFileSync(join(work, rel), body);
		}
		gitIn(work, ['add', '-A']);
		const ts = new Date(Date.now() - ageHours * 3_600_000).toISOString();
		gitIn(work, ['commit', '-qm', 'fixture'], { GIT_AUTHOR_DATE: ts, GIT_COMMITTER_DATE: ts });
	}
	gitIn(work, ['push', '-q', bare, 'HEAD:main']);
}

const CONSUMER_PKG = JSON.stringify({ name: 'x', dependencies: { '@wolffm/themes': '^1.0.0' } });

/** A repo consuming `@wolffm/themes`, with ONE commit backdated `ageHours` ago. */
function makeAgedRepo(fx, name, ageHours) {
	pushDated(fx, name, [{ files: { 'package.json': CONSUMER_PKG }, ageHours }]);
}

function run(fx, { argv = ['--json', '--no-registry'], env = {} } = {}) {
	try {
		const out = execFileSync('node', [SCRIPT, ...argv], {
			env: {
				...NO_GIT_ENV,
				...fx.remotes.env,
				FIXTURE_REMOTES: join(fx.root, 'remotes'),
				PATH: `${fx.bin}:${process.env.PATH}`,
				REPOS_DIR: fx.reposDir,
				HADOKU_SITE_ROOT: fx.siteRoot,
				FLEET_MANIFEST_DIR: fx.manifestDir,
				...env,
			},
			encoding: 'utf8',
			stdio: ['ignore', 'pipe', 'pipe'],
		});
		return { code: 0, out, stderr: '' };
	} catch (e) {
		return { code: e.status ?? -1, out: String(e.stdout ?? ''), stderr: String(e.stderr ?? '') };
	}
}

function findingsFor(doc, repo) {
	return (doc.findings ?? []).filter((f) => f.repo === repo);
}
function advisoriesFor(doc, repo) {
	return (doc.advisory ?? []).filter((f) => f.repo === repo);
}

test('a 3-hour-old repo is ADVISORY new-repo-grace, not a failing finding, and the run exits 0', () => {
	const fx = fixture();
	try {
		makeAgedRepo(fx, 'repo-new', 3);
		const { code, out } = run(fx);
		const doc = JSON.parse(out);

		assert.deepEqual(findingsFor(doc, 'repo-new'), [], 'must not be a failing finding');
		const adv = advisoriesFor(doc, 'repo-new');
		assert.equal(adv.length, 1);
		assert.equal(adv[0].rule, 'new-repo-grace');
		assert.ok(adv[0].meta.ageHours < 24, `expected < 24h, got ${adv[0].meta.ageHours}`);
		assert.equal(code, 0, `expected exit 0 with only an advisory, got ${code}: ${out}`);
	} finally {
		cleanup(fx);
	}
});

test('a 30-hour-old repo FAILS as not-in-fleet (past the grace), run exits 1', () => {
	const fx = fixture();
	try {
		makeAgedRepo(fx, 'repo-old', 30);
		const { code, out } = run(fx);
		const doc = JSON.parse(out);

		assert.deepEqual(advisoriesFor(doc, 'repo-old'), [], 'must not be advisory past the grace');
		const found = findingsFor(doc, 'repo-old');
		assert.equal(found.length, 1);
		assert.equal(found[0].rule, 'not-in-fleet');
		assert.equal(code, 1, `expected exit 1 on a real not-in-fleet finding, got ${code}: ${out}`);
	} finally {
		cleanup(fx);
	}
});

test('age is the FIRST commit, not the newest: a 100h-old repo touched 1h ago FAILS', () => {
	const fx = fixture();
	try {
		// The consumer appears only in the 1h-old commit. Reading the NEWEST
		// commit's date would misread this repo as brand new and wrongly grant
		// the grace.
		pushDated(fx, 'repo-touched', [
			{ files: { 'package.json': JSON.stringify({ name: 'x' }) }, ageHours: 100 },
			{ files: { 'package.json': CONSUMER_PKG }, ageHours: 1 },
		]);
		const { code, out } = run(fx);
		const doc = JSON.parse(out);

		assert.deepEqual(advisoriesFor(doc, 'repo-touched'), [], 'a 100h-old repo earns no grace');
		const found = findingsFor(doc, 'repo-touched');
		assert.equal(found.length, 1);
		assert.equal(found[0].rule, 'not-in-fleet');
		assert.equal(code, 1, `expected exit 1, got ${code}: ${out}`);
	} finally {
		cleanup(fx);
	}
});

test('a clean fleet (nothing out of roster) is still exit 0 with no advisories', () => {
	const fx = fixture();
	try {
		// The account holds at least the hub. A listing of ZERO repos is a broken
		// read, and is its own failure (`unreadable` against the owner).
		makeHub(fx);
		const { code, out } = run(fx);
		const doc = JSON.parse(out);
		assert.deepEqual(doc.findings, []);
		assert.deepEqual(doc.advisory, []);
		assert.equal(code, 0);
	} finally {
		cleanup(fx);
	}
});

// ── #98: the per-repo rules, mutation-tested ───────────────────────────────
//
// Everything above runs with an EMPTY `uiApp` facet, so the per-repo loop —
// where every rule but `not-in-fleet` lives — never ran under test at all.
// Below, one fixture app that is CLEAN under every rule (the floor: without it
// each case is vacuous), then one minimal violation per case, each of which
// exited 0 before #98.

const APP = 'app-x';
const APP_ROSTER = {
	repos: [`WolffM/${APP}`],
	facets: {
		[`WolffM/${APP}`]: { uiApp: true, wolffmConsumer: ['@wolffm/task-ui-components'] },
	},
};

const CLEAN_APP = {
	'package.json': JSON.stringify({
		name: APP,
		dependencies: { '@wolffm/task-ui-components': '^1.0.0' },
	}),
	'pnpm-workspace.yaml': "packages:\n  - '.'\nminimumReleaseAgeExclude:\n  - '@wolffm/*'\n",
	'.github/workflows/update-wolffm.yml':
		'jobs:\n  update:\n    steps:\n      - uses: actions/checkout@v6\n' +
		'      - uses: example/actions/update-wolffm@v1\n',
	'vite.config.ts': 'export default {};\n',
	'index.html': '<html><head><link rel="icon" href="/favicon.svg"></head></html>\n',
	'src/App.tsx':
		"import { AppHeader } from '@wolffm/task-ui-components';\n" +
		"import { HadokuThemeRoot } from '@wolffm/themes';\n" +
		'export function App({ appName }) {\n' +
		'  return (\n' +
		'    <HadokuThemeRoot>\n' +
		'      <AppHeader title={appName ?? __HADOKU_APP_NAME__} />\n' +
		'    </HadokuThemeRoot>\n' +
		'  );\n' +
		'}\n',
};

/** A repo whose shipped default branch holds exactly `files` (path -> content). */
function makeRepo(fx, name, files) {
	fx.remotes.push(`WolffM/${name}`, files);
}

/** The hub's catalogue files. */
function hubFiles(childApps = [{ id: 'appx', repoName: APP }]) {
	return {
		'spec/categories.json': JSON.stringify({
			categories: [{ apps: [{ id: 'appx', label: 'App X' }] }],
		}),
		'scripts/child-apps.json': JSON.stringify({ apps: childApps }),
	};
}

/** The hub's catalogue, on the hub's shipped branch — where `catalogue()` reads it. */
function makeHub(fx, childApps) {
	makeRepo(fx, 'hadoku_site', hubFiles(childApps));
}

/** A fleet of one app: CLEAN_APP with `changes` applied. */
function appFixture(changes = {}, { hub = true, childApps } = {}) {
	const fx = fixture(APP_ROSTER);
	if (hub) makeHub(fx, childApps);
	makeRepo(fx, APP, { ...CLEAN_APP, ...changes });
	return fx;
}

function rulesFor(doc, repo = APP) {
	return findingsFor(doc, repo).map((f) => f.rule);
}

test('#98 floor: the fixture app is clean under every rule, exit 0', () => {
	const fx = appFixture();
	try {
		const { code, out } = run(fx);
		const doc = JSON.parse(out);
		assert.deepEqual(doc.findings, [], out);
		assert.equal(code, 0);
	} finally {
		cleanup(fx);
	}
});

test('#98: an unreadable catalogue is reported ONCE, against the hub — it used to silence both header-name rules', () => {
	const fx = appFixture({}, { hub: false });
	try {
		const { code, out } = run(fx);
		const doc = JSON.parse(out);
		const blind = findingsFor(doc, 'hadoku_site');
		assert.equal(blind.length, 1, out);
		assert.equal(blind[0].rule, 'catalogue-unreadable');
		assert.match(blind[0].detail, new RegExp(APP));
		assert.equal(code, 1);
	} finally {
		cleanup(fx);
	}
});

// F7 (plan §4.1): categories.json readable, child-apps.json specifically
// missing — the one line this migration touched, isolated from the "the
// whole hub is unreadable" case above. `catalogue()`'s outer try/catch
// already degraded this to `readable: false` under the OLD
// `JSON.parse(readFile(...))` shape too (`readFile` returns `null` on a miss,
// `JSON.parse(null)` is the JS value `null`, and `null.apps` throws) — so this
// is a BEHAVIOUR-PRESERVED check, not a mutation witness; the test below it
// (source topology) is what actually goes red on a revert to that shape.
test('#98: categories.json readable, child-apps.json missing, is still catalogue-unreadable', () => {
	const fx = appFixture({}, { hub: false });
	try {
		makeRepo(fx, 'hadoku_site', {
			'spec/categories.json': JSON.stringify({
				categories: [{ apps: [{ id: 'appx', label: 'App X' }] }],
			}),
		});
		makeRepo(fx, APP, CLEAN_APP);
		const { code, out } = run(fx);
		const doc = JSON.parse(out);
		const blind = findingsFor(doc, 'hadoku_site');
		assert.equal(blind.length, 1, out);
		assert.equal(blind[0].rule, 'catalogue-unreadable');
		assert.equal(code, 1);
	} finally {
		cleanup(fx);
	}
});

// F7's actual mutation witness: `catalogue()` reads child-apps.json through
// `readChildApps({read})`, not a bare `JSON.parse`. MUTATION: put
// `JSON.parse(readFile(site, 'scripts/child-apps.json'))` back and this goes
// red even though the runtime test above still passes (see its own comment).
test('#98: the catalogue reads child-apps.json through site-docs.mjs, not a bare JSON.parse', () => {
	const src = readFileSync(SCRIPT, 'utf8');
	assert.match(src, /import \{ readChildApps \} from '\.\/lib\/site-docs\.mjs';/);
	const fn = src.slice(src.indexOf('function catalogue()'), src.indexOf('// ---- the catalogue'));
	assert.match(fn, /readChildApps\(\{\s*read:\s*\(file\)\s*=>\s*readFile\(site,\s*file\)\s*\}\)/);
	assert.doesNotMatch(fn, /JSON\.parse\(readFile\(site, 'scripts\/child-apps\.json'\)\)/);
});

