/** PATH with an `npm` first that prints `stdout` and exits `code`. */
function npmShim(fx, { stdout = '', code = 0 }) {
	const bin = join(fx.root, `bin-${code}`);
	mkdirSync(bin, { recursive: true });
	const p = join(bin, 'npm');
	writeFileSync(p, `#!/bin/sh\nprintf '%s' '${stdout}'\nexit ${code}\n`);
	chmodSync(p, 0o755);
	return { PATH: `${bin}:${fx.bin}:${process.env.PATH}` };
}

test('#98: a registry it could not read FAILS the exit code, not just the JSON field', () => {
	const fx = appFixture();
	try {
		const argv = ['--json'];
		// Control: the registry answers with the declared version — clean, exit 0.
		const ok = run(fx, { argv, env: npmShim(fx, { stdout: '1.0.0' }) });
		assert.equal(ok.code, 0, ok.out);
		assert.equal(JSON.parse(ok.out).registry.blind, false);

		const blind = run(fx, { argv, env: npmShim(fx, { code: 1 }) });
		const doc = JSON.parse(blind.out);
		assert.equal(doc.registry.blind, true);
		assert.deepEqual(doc.findings, []);
		assert.equal(blind.code, 1, 'a blind registry must not exit 0');
	} finally {
		cleanup(fx);
	}
});

